def calc_distance_numpy(x1, y1, x2, y2):
    x1_r = np.radians(x1)
    x2_r = np.radians(x2)
    y1_r = np.radians(y1)
    y2_r = np.radians(y2)
    return 6371 * np.arccos(
        np.sin(x1_r) * np.sin(x2_r) + np.cos(x1_r) * np.cos(x2_r) * np.cos(y1_r - y2_r)
    )


